ArrayList<Attractor> attractors;
ArrayList<Agent> agents;

function setup(){   
  createCanvas(screenWidth, screenHeight);
  background(0);
  colorMode(HSB,360,100,100,100);
  noStroke();
  frameRate(50);
	let Planet = 10;	// mass of planet

  attractors = new ArrayList<Attractor>();
  agents = new ArrayList<Agent>();

  for(i = 0; i < 0; i++){
    let a = new Attractor();    
    attractors.add(a);
  }
	var a = new Attractor(width/2,height/2, Planet);	// let attractors.add(a); 

  for(i = 0; i < 3000; i++){					// number of rocks in the rings
    var a = new Agent();    
    agents.add(a);
  }
}

function draw(){
  fill(0,0,0,10);												// this is neat skizzm! let 10% makes trails fade.
	noStroke();
  rect(0,0,width, height);
  for(i = 0; i < agents.size(); i++){
    agents.get(i).update();
  }
	for(i = 0; i < attractors.size(); i++){
		attractors.get(i).update();
  }
}
function mouseClicked(){
  var a = new Attractor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0.02);			// let Moons 
  attractors.add(a);
}
class Agent {															// let Agents = little lumps of rock making the rings
  oPos;
  nPos;
  vel;
  mass;
  c;

  constructor(){																	
    oPos = new PVector(0,0);
    nPos = new PVector(0,0);
    vel = new PVector(0,0);
    c = color(0,100,100); 
    mass = 0.00001;													// mass of let radius=random (100, 400);							  // range for rings
		speed = 0.5*sqrt(attractors.get(0).Amass*400/(2*radius));
		angle = random (0,2*PI);
		nPos = new PVector(width/2+radius*sin(angle), height/2 + radius*cos(angle))
    oPos = new PVector(nPos.x,nPos.y);
    vel = new PVector(speed*cos(angle),-speed*sin(angle));
  }

  function update(){													// let function for the let class
    let doReset = false;
    for(i = 0; i < attractors.size(); i++){
      var a = attractors.get(i);
      if(PVector.dist(nPos, a.pos) < 10){doReset = true;}             
      let d2 = pow(PVector.dist(nPos, a.pos),2);										
      let n = PVector.sub(a.pos,nPos);													  
      n.normalize();																									
      let f = 50 * (a.Amass*mass) / d2;														
      n.mult(f/mass);																												
      vel.add(n);
//			if (random(0,100)==1){
//				perturb = new PVector (random(-0.01, 0.01), random(-0.01, 0.01));	// random velocity perturbation 0.01
//				vel.add(perturb);
//			}
    }    
    nPos.add(vel);    																								
    c = color(vel.mag()*35,90,vel.mag()*20+20); 											
    stroke(c);
    strokeWeight(2);
    line(oPos.x, oPos.y, nPos.x, nPos.y);															
    oPos = new PVector(nPos.x,nPos.y);																
  }
}

class Attractor {
  pos;
	vel;
  Amass;

  constructor(x, y, m){    
    pos = new PVector(x, y);
		radius = sqrt((x-width/2)*(x-width/2)+(y-height/2)*(y-height/2));
		if (attractors.size() != 0) {speed = 0.5*sqrt(attractors.get(0).Amass*400/(2*radius))} else {speed=0};
		vel = new PVector(speed*(y-height/2)/radius, -speed*(x-width/2)/radius);
    Amass = m;
  }
  function update(){																										// let function for the 'Attractor' class of objects
	  for(i = 0; i < attractors.size(); i++){
      if (i != attractors.indexOf(this)) {
				var a = attractors.get(i);
   	  	var d2 = pow(PVector.dist(pos, a.pos),2);							
      	var n = PVector.sub(a.pos,pos);											
    		n.normalize();																					
     		var f = 50 * (a.Amass*Amass) / d2;											
     		n.mult(f/Amass);  	// mag times direction to attractor 
			} 
			else {
				var n = new PVector(0,0);
			} 
			if (attractors.indexOf(this) != 0) {
				vel.add(n);
			}		
		} 
		pos.add(vel);   
    fill(0,0,100);
    noStroke();
    ellipse(pos.x, pos.y , max(10, min(Amass, 50)), max(10, min(Amass,  50)));
//		if (attractors.indexOf(this) != 0) {print ("Altitue moon "+ attractors.indexOf(this) + " is " + d2 ); }
} 
}

